application.css:
* { box-sizing: border-box; }

:root {
  --ink: #17213b;
  --muted: #707991;
  --line: #e7eaf2;
  --accent: #6957e8;
  --accent-dark: #5140ca;
  --soft: #f5f3ff;
  --green: #1c9a71;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: radial-gradient(circle at 15% 10%, #e9e5ff 0, transparent 31%), linear-gradient(135deg, #f8f9fd 0%, #eef0f8 100%);
}

.page-shell { width: min(100% - 32px, 780px); margin: 0 auto; padding: 54px 0 30px; }
.quiz-card { overflow: hidden; background: #fff; border: 1px solid rgba(222, 225, 237, .8); border-radius: 24px; box-shadow: 0 22px 60px rgba(45, 47, 85, .12); }
.quiz-header { padding: 42px 48px 34px; background: linear-gradient(120deg, #29265d, #5146a6); color: white; }
.eyebrow { font-size: 11px; font-weight: 800; letter-spacing: .18em; opacity: .7; }
h1 { margin: 12px 0 8px; font-size: clamp(30px, 5vw, 42px); letter-spacing: -.04em; }
.quiz-header p { margin: 0; color: #d8d8f2; font-size: 15px; }
.question-list { padding: 10px 48px 0; }
.question { margin: 0; padding: 28px 0 25px; border: 0; border-bottom: 1px solid var(--line); }
.question legend { display: flex; gap: 16px; align-items: flex-start; width: 100%; padding: 0; font-size: 17px; font-weight: 700; line-height: 1.45; }
.question-number { flex: 0 0 auto; color: var(--accent); font-size: 12px; letter-spacing: .08em; font-weight: 800; padding-top: 4px; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin: 19px 0 0 36px; }
.option { display: flex; align-items: center; gap: 10px; min-height: 46px; padding: 10px 13px; border: 1px solid var(--line); border-radius: 10px; color: #4b5670; font-size: 14px; cursor: pointer; transition: .18s ease; }
.option:hover { border-color: #b9b1fa; background: var(--soft); color: var(--ink); }
.option:has(input:checked) { border-color: var(--accent); background: var(--soft); color: var(--accent-dark); font-weight: 700; box-shadow: 0 0 0 2px rgba(105, 87, 232, .08); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.custom-radio { width: 16px; height: 16px; flex: 0 0 16px; border: 1.5px solid #c5c9d7; border-radius: 50%; position: relative; }
.option:has(input:checked) .custom-radio { border-color: var(--accent); }
.option:has(input:checked) .custom-radio:after { content: ""; position: absolute; inset: 3px; background: var(--accent); border-radius: 50%; }
.quiz-footer { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 28px 48px 34px; }
.status { min-height: 20px; margin: 0; color: #c14c5c; font-size: 13px; font-weight: 600; }
button { border: 0; border-radius: 10px; padding: 14px 21px; color: white; background: var(--accent); font: inherit; font-size: 14px; font-weight: 750; cursor: pointer; box-shadow: 0 8px 18px rgba(105, 87, 232, .22); transition: .18s ease; }
button:hover { background: var(--accent-dark); transform: translateY(-1px); }
button span { margin-left: 9px; font-size: 18px; }
.result { display: none; margin: 0 48px 38px; padding: 23px; text-align: center; border-radius: 15px; background: #f0fbf7; border: 1px solid #ccefe2; }
.result.visible { display: block; }
.result-label { color: var(--green); font-size: 11px; font-weight: 800; letter-spacing: .16em; }
.score { margin: 4px 0 0; color: var(--green); font-size: 42px; font-weight: 850; letter-spacing: -.05em; }
.result-message { color: #507469; font-size: 13px; }
.page-note { margin-top: 18px; color: #8b92a8; text-align: center; font-size: 12px; }
@media (max-width: 620px) { .page-shell { width: min(100% - 20px, 780px); padding-top: 20px; } .quiz-header, .question-list { padding-left: 24px; padding-right: 24px; } .quiz-footer { padding-left: 24px; padding-right: 24px; align-items: flex-end; } .options { grid-template-columns: 1fr; margin-left: 0; } .result { margin-left: 24px; margin-right: 24px; } }

application.javascript:
const form = document.getElementById('quiz-form');
const status = document.getElementById('status');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const result = document.querySelector('.result');
const resultMessage = document.getElementById('result-message');
const answers = { q1: 'jupiter', q2: 'css', q3: 'six' };

form.addEventListener('submit', function (event) {
  event.preventDefault();
  const data = new FormData(form);
  const unanswered = ['q1', 'q2', 'q3'].filter(name => !data.get(name));

  if (unanswered.length) {
    status.textContent = 'Please choose one answer for each question.';
    result.classList.remove('visible');
    scoreElement.textContent = '';
    scoreElement.removeAttribute('data-score');
    return;
  }

  status.textContent = '';
  let score = 0;
  Object.keys(answers).forEach(name => {
    if (data.get(name) === answers[name]) score++;
  });

  scoreElement.textContent = `${score} / 3`;
  scoreElement.setAttribute('data-score', String(score));
  resultMessage.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Keep practicing and try again.' : 'Nice effort — you can try again to improve.';
  result.classList.add('visible');
});
